INSERT INTO `pdf_index` VALUES (3243, 103, 'According to the reported data, the current income of healthcare organizations amounted to 2818.6 billion tenge, of which the share of hospital income was 58.1%, other activities for the protection of human health - 15.4%, general medical practice - 14.7%, special medical practice - 5.2%, activities in the field of social services - 3.7%, dental activities - 2.8%.', '2 818.6 billion', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3244, 103, 'The current expenses of healthcare organizations in 2021 amounted to 2690.1 billion tenge, of which the largest share was the cost of maintaining the labor force - 1369.5 billion tenge (50.9%) and the cost of purchased services - 428.1 billion. tenge (15.9%). The remaining expenses amounted to 892.4 billion tenge (33.2%).', '2 690.1 billion', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3245, 104, 'In 2021, there were 162 organizations of rehabilitation treatment and medical rehabilitation in the Republic of Kazakhstan, including 99 sanatoriums, 25 rehabilitation centers, 21 other organizations, 9 dispensaries and 8 specialized sanatoriums.', '162', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3246, 104, 'In the reporting year, the number of doctors of sanatorium organizations in these organizations amounted to 537 people, including 357 women (66.5%). The number of paramedical personnel amounted to 1973 people, including 1804 women (91.4%).', '537', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3247, 104, 'In 2021, the number of sanatorium beds amounted to 19681 units, including 3789 sanatorium beds for children.', '19681', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3248, 105, 'At the end of 2021, there were 272 organizations in the Republic of Kazakhstan providing special social services, of which 171 were stationary, 69 semi-stationary, 31 temporary stay, and 1 with several conditions for the provision of special social services.', '272', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3249, 105, 'At the end of 2021, the number of people living in these organizations amounted to 37973 people, including pensioners by age - 12096 people (31.9%), participants and invalids of the Great Patriotic War - 18 people (0.05%).', '37 973', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3250, 106, 'According to the results of the survey, the share of people who trust the prosecutor\'s office was 63.8%, partially trusting – 27.1%, rather distrustful – 3.0%, distrustful - 2.9%. The share of those who found it difficult to answer was 3.2%.', '63.8%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3251, 106, 'The proportion of those who fully agree with the statement that the police can be trusted was 63.1%, partially agree – 27.8%, partially disagree – 3.6%, completely disagree – 3.9%. The proportion of those who have never encountered the police was 1.7%.', '63.1%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3252, 106, 'The proportion of those who fully agree with the statement that the anti-corruption service can be trusted was 51.1%, partially agree – 31.1%, partially disagree - 5.3%, completely disagree - 3.9%. The share of those who have never encountered the anti-corruption service was 8.6%.', '51.1%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3253, 106, '46.3% fully agree with the statement that the Economic Investigation Service can be trusted, 31.5% partially agree, 5.5% partially disagree, and 3.6% completely disagree. The share of those who have never encountered the Economic Investigation Service was 13.1%.', '46.3%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3254, 106, 'Trusting the judicial system – 61.0%, partially trusting – 28.1%, rather distrustful - 2.7%, distrustful - 3.2%. The share of those who found it difficult to answer was 5.0%.', '61.0%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3255, 106, 'The proportion of those who trust the fire service was 77.2%, partially trusting – 17.9%, rather distrustful – 1.0%, distrustful – 1.0%. The share of those who found it difficult to answer was 3.0%.', '77.2%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3256, 107, 'According to the results of the survey, the share of people who trust the prosecutor\'s office was 57.1%, partially trusting - 30.6%, rather distrustful - 4.0%, distrustful - 3.9%. The share of those who found it difficult to answer was 4.4%.', '57.1%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3257, 107, 'The proportion of those who trust the police was 57.5%, partially trusting - 30.5%, rather distrustful - 3.9%, distrustful - 4.3%. The share of those who found it difficult to answer was 3.8%.', '57.5%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3258, 107, 'The share of those who trust the anti-corruption service was 43.4%, partially trusting - 32.6%, rather distrustful - 5.7%, distrustful - 5.5%. The share of those who found it difficult to answer was 12.8%.', '43.4%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3259, 107, 'The proportion of those who trust the fire service was 72.1%, partially trusting - 22.4%, rather distrustful - 1.2%, distrustful - 1.1%. The share of those who found it difficult to answer was 3.2%.', '72.1%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3260, 107, 'Trusting the economic investigation service - 40.2%, partially trusting - 32.2%, rather distrustful - 5.8%, distrustful - 4.6%. The share of those who found it difficult to answer was 17.3%.', '40.2%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3261, 107, 'Trusting the judicial system - 55.2%, partially trusting - 31.0%, rather distrustful - 3.7%, distrustful - 4.0%. The share of those who found it difficult to answer was 6.1%.', '55.2%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
