INSERT INTO `pdf_index` VALUES (3300, 118, 'As of January 1, 2024 in the Republic of Kazakhstan: 3924 public libraries, 3069 cultural and leisure organizations, 275 museums, 230 entertainment and recreation parks, 113 cinemas, 74 theaters, 43 concert organizations, 11 zoos and 3 circuses', '3924', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3301, 118, 'In 2023 the most visited were libraries (52663.2 thousand visits), cinemas (20995.7 thousand visits), entertainment and rest parks (14729.2 thousand visits), museums (6255.9 thousand visits). At the same time, the most of the events were held by cultural and leisure organizations (206.0 thousand units), theaters (16.5 thousand units), entertainment and rest parks (7.1 thousand units) and concert organizations (6.4 thousand units)', '52663.2 thousand', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3302, 118, 'In the regional context, in 2023, the most visited libraries are in Almaty city (5368.8 thousand visits), Turkestan (3976.4 thousand visits), Akmola (3715.2 thousand visits) and Abai (3463.6 thousand visits) regions. The largest attendance of cinema shows falls on the cities of republican significance: Almaty city – 7111.6 thousand visits, Astana city – 4346.7 thousand visits, Shymkent city – 1721.4  thousand visits. Most museums are visited in Turkestan region (1285.8 thousand visits) and Astana city (890.4 thousand visits)', '5368.8 thousand', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3303, 119, 'As of January 1, 2023 in the Republic of Kazakhstan,: 3917 public libraries, 3102 cultural and leisure organizations, 271 museums, 208 entertainment and recreation parks, 105 cinemas, 73 theaters, 44 concert organizations, 13 zoos and 3 circuses.', '3917', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3304, 119, 'In 2022 the most visited were libraries (51239.3 thousand visits), cinemas (17047.5 thousand visits), entertainment and rest parks (14273.7 thousand visits), museums (6097.3 thousand visits). At the same time, the most of the events were held by cultural and leisure organizations (196.7 thousand units), theaters (15.4 thousand units), entertainment and rest parks (6.7 thousand units) and concert organizations (5.9 thousand units).', '51239.3 thousand', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3305, 119, 'In the regional context, in 2022, the most visited libraries are in Almaty city (5830.1 thousand visits), Turkestan (3914.3 thousand visits), Akmola (3518.2 thousand visits) and Abai (3457.3 thousand visits) regions. The largest attendance of cinema shows falls on the cities of republican significance: Almaty city – 6233.1 thousand visits, Astana city – 3552 thousand visits, Shymkent city – 1264.7 thousand visits. Most museums are visited in Turkestan region (1492.5 thousand visits) and Astana city (643.1 thousand visits).', '5830.1 thousand', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
