INSERT INTO `pdf_index` VALUES (3548, 240, 'Employment rate to the population aged 15 years and older in the 2st quarter of 2023 amounted to 65.6%, to the labor force - 95.3%. Unemployment rate (according to the methodology of the International Labor Organization) for amounted to 4.8%. The number of unemployed (according to ILO methodology) amounted to 452.6 thousand people. The proportion of NEET youth who are neither employed nor engaged in education or training was 7.5%', '65.6%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
