INSERT INTO `pdf_index` VALUES (3577, 251, 'The highest level of poverty in 2023 was registered in Turkestan region (9%), and the lowest –  in the   city of Astana (2.4%)', '9%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3578, 252, 'In 2023 monetary expenditures of the population on average per capita amounted to 1 072 978 tenge, which is 15.2% higher than in the corresponding quarter of the previous year. The average per capita incomes of the population amounted to 1 161 847 tenge, which is 20.5% higher than in the corresponding quarter of the previous year', '1 072 978', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3579, 252, 'The income used for consumption, on average per capita for 2023, amounted to 1 092 243 tenge, which is 14.9% higher than in the previous year', '1 092 243', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3580, 253, 'In 2023, the cost of consumer goods in comparable prices produced by households increased by 9.4% compared to the previous year', '9.4%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3581, 254, 'Meat and meat products (17%), bread products and cereals (7.9%) account for the largest share of food purchase expenses in household consumer spending, as in previous periods. The highest level of consumption of meat and meat products is observed in Atyrau, Akmola, Zhetysu regions, and the lowest is in the city of Shymkent.', '17%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3582, 255, 'The average per capita nominal monetary incomes of the population, according to estimates in the fourth quarter of 2023, amounted to 194856 tenge per month, which is 14.4% higher than in the second quarter of 2022, real monetary incomes increased by 3.7% the specified period', '194 856', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3583, 256, 'According to the results of a sample survey of households, the share of the population with incomes below the subsistence minimum (poverty level) in the IV quarter of 2023 was 5.1%', '5.1%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3584, 256, 'The highest level of poverty in the IV quarter of 2023 was registered in Turkestan (8.7%) region, and the lowest –  in the   city of Astana (2.4%)', '8.7%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3585, 257, 'In the fourth quarter of 2023, the cost of consumer goods in comparable prices produced by households increased by 14.4% compared to the corresponding quarter of the previous year.', '14.4%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3586, 258, 'In the fourth quarter of 2023 monetary expenditures of the population on average per capita amounted to 277 202 tenge, which is 12.3% higher than in the corresponding quarter of the previous year. The average per capita incomes of the population amounted to 305 884 tenge, which is 21.2% higher than in the corresponding quarter of the previous year', '277 202 tenge', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3587, 258, 'The income used for consumption, on average per capita for the fourth quarter of 2023, amounted to 282 072 tenge, which is 11.9% higher than in the corresponding quarter of the previous year. Considering the regional aspect, the largest income growth can be noted in the city of Astana. Among the regions with the lowest level of income used for consumption recorded in the city of Shymkent and in the Turkestan region. The income level in these regions is 27% lower than the national average', '282 072 tenge', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
INSERT INTO `pdf_index` VALUES (3588, 259, 'Meat and meat products (17.4%), bread products and cereals (8%) account for the largest share of food purchase expenses in household consumer spending, as in previous periods. The highest level of consumption of meat and meat products is observed in Zhetysu, Zhambyl, Akmola  regions, and the lowest is in the city of Shymkent', '17.4%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
