INSERT INTO `pdf_index` VALUES (3590, 262, 'In the third quarter of 2023, the cost of consumer goods in comparable prices produced in increased by 8.4% compared to the corresponding quarter of the previous year.', '8.4%', '2024-05-04 04:56:14', '2024-05-04 04:56:14', 0);
